/* From Uiverse.io by anniekoop  - Tags: simple, neumorphism, action, alert, minimalist, notification, card, light */
.__UIV_SCOPE__ .card {
  width: fit-content;
  background-color: #f2f3f7;
  border-radius: 0.75em;
  cursor: pointer;
  transition: ease 0.2s;
  box-shadow: 1em 1em 1em #d8dae0b1, -0.75em -0.75em 1em #ffffff;
  border: 1.5px solid #f2f3f7;
}

.__UIV_SCOPE__ .card:hover {
  background-color: #d3ddf1;
  border: 1.5px solid #1677ff;
}

.__UIV_SCOPE__ .container {
  margin-top: 1.25em;
  margin-bottom: 1.375em;
  margin-left: 1.375em;
  margin-right: 2em;
  display: flex;
  flex-direction: row;
  gap: 0.75em;
}

.__UIV_SCOPE__ .status-ind {
  width: 0.625em;
  height: 0.625em;
  background-color: #ff0000;
  margin: 0.375em 0;
  border-radius: 0.5em;
}

.__UIV_SCOPE__ .text-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.25em;
  color: #333;
}

.__UIV_SCOPE__ .time {
  font-size: 0.875em;
  color: #777;
}

.__UIV_SCOPE__ .text-link {
  font-weight: 500;
  text-decoration: none;
  color: black;
}

.__UIV_SCOPE__ .button-wrap {
  display: flex;
  flex-direction: row;
  gap: 1em;
  align-items: center;
}

.__UIV_SCOPE__ .secondary-cta {
  background-color: transparent;
  border: none;
  font-size: 15px;
  font-weight: 400;
  color: #666;
  cursor: pointer;
}

.__UIV_SCOPE__ .primary-cta {
  font-size: 15px;
  background-color: transparent;
  font-weight: 600;
  color: #1677ff;
  border: none;
  border-radius: 1.5em;
  cursor: pointer;
}

.__UIV_SCOPE__ button:hover {
  text-decoration: underline;
}

.__UIV_SCOPE__ .right {
  display: flex;
  flex-direction: column;
  gap: 0.875em;
}
